// Turn each uploaded context document into its own item.
// Text files are decoded here; PDFs keep their binary for "Extract PDF Text".
const TEXT_EXTENSIONS = ['txt', 'md', 'csv', 'json', 'html', 'htm'];
const binary = $input.first().binary ?? {};
const keys = Object.keys(binary).filter((key) => key.startsWith('Context_Documents'));

const items = [];
for (const key of keys) {
  const file = binary[key];
  const extension = (file.fileExtension || file.fileName?.split('.').pop() || '').toLowerCase();

  if (file.mimeType === 'application/pdf' || extension === 'pdf') {
    items.push({ json: { fileName: file.fileName, fileType: 'pdf' }, binary: { data: file } });
  } else if (TEXT_EXTENSIONS.includes(extension) || file.mimeType?.startsWith('text/')) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    items.push({ json: { fileName: file.fileName, fileType: 'text', text: buffer.toString('utf8') } });
  }
}

// Always emit at least one item so the workflow continues when no documents are uploaded
return items.length ? items : [{ json: { fileType: 'none' } }];

// Combine the text of every context document into one block for the agent prompt.
const MAX_CHARS_PER_DOC = 20000;
const MAX_TOTAL_CHARS = 60000;

const sections = [];
for (const [i, item] of $input.all().entries()) {
  if (item.json.fileType === 'none') continue;

  const text = String(item.json.text ?? '').trim();
  if (!text) continue;

  // PDF extraction drops the original JSON, so recover the file name from the split step
  let fileName = item.json.fileName;
  if (!fileName) {
    try {
      fileName = $('Split Context Documents').itemMatching(i).json.fileName;
    } catch (error) {
      fileName = `Document ${i + 1}`;
    }
  }

  sections.push(`#### ${fileName}\n${text.slice(0, MAX_CHARS_PER_DOC)}`);
}

return [{
  json: {
    documentCount: sections.length,
    documentContext: sections.length
      ? sections.join('\n\n---\n\n').slice(0, MAX_TOTAL_CHARS)
      : 'No context documents were provided.',
  },
}];

// Rank recent Instagram posts by engagement and keep the top 3 for the rules step.
// "Get Post Insights" emits one item per post (failed requests included), so indexes line up with "Split Out Posts".
const TOP_N = 3;
const MIN_AGE_HOURS = 48; // insights can lag up to 48h, so brand-new posts would rank unfairly low

const insights = $input.all();
const posts = $('Split Out Posts').all()
  .map(({ json: post }, i) => {
    const metrics = {};
    for (const metric of insights[i]?.json.data ?? []) {
      metrics[metric.name] = metric.values?.[0]?.value ?? metric.total_value?.value ?? 0;
    }

    const likes = post.like_count ?? 0;
    const comments = post.comments_count ?? 0;
    const engagement = metrics.total_interactions
      ?? likes + comments + (metrics.saved ?? 0) + (metrics.shares ?? 0);

    return {
      caption: post.caption ?? '',
      mediaType: post.media_type,
      productType: post.media_product_type,
      permalink: post.permalink,
      postedAt: post.timestamp,
      likes,
      comments,
      saves: metrics.saved ?? null,
      shares: metrics.shares ?? null,
      reach: metrics.reach ?? null,
      engagement,
      engagementRatePercent: metrics.reach ? Number(((engagement / metrics.reach) * 100).toFixed(2)) : null,
    };
  })
  .filter((post) => post.caption);

const cutoff = Date.now() - MIN_AGE_HOURS * 60 * 60 * 1000;
const settled = posts.filter((post) => new Date(post.postedAt).getTime() <= cutoff);
const pool = settled.length >= TOP_N ? settled : posts;

const topPosts = pool.sort((a, b) => b.engagement - a.engagement).slice(0, TOP_N);

return [{ json: { postsAnalyzed: pool.length, topPosts } }];

// Turn the fetched blog page into plain text for the summarizer.
const MAX_CHARS = 30000;
const page = $input.first().json;
const html = String(page.data ?? '');

const pick = (pattern) => html.match(pattern)?.[1] ?? '';
const decode = (text) => text
  .replace(/&nbsp;/g, ' ')
  .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
  .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
  .replace(/&rsquo;|&lsquo;/g, "'")
  .replace(/&rdquo;|&ldquo;|&quot;/g, '"')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

// Prefer the article body; fall back to <main>, then the whole <body>
const content = pick(/<article[^>]*>([\s\S]*)<\/article>/i)
  || pick(/<main[^>]*>([\s\S]*)<\/main>/i)
  || pick(/<body[^>]*>([\s\S]*)<\/body>/i)
  || html;

const text = decode(content
  .replace(/<(script|style|noscript|svg|nav|header|footer|aside|form|iframe)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr|section|blockquote)>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ')
  .replace(/\s*\n\s*/g, '\n')
  .trim();

return [{
  json: {
    title: decode(pick(/<title[^>]*>([\s\S]*?)<\/title>/i)).trim(),
    text: text.slice(0, MAX_CHARS),
    fetchError: page.error?.message ?? null,
  },
}];
